"use client";

import { useState } from "react";
import { GoogleMap, LoadScript, Marker } from "@react-google-maps/api";

interface Hotel {
  name: string;
  vicinity: string;
  geometry: {
    location: {
      lat: number;
      lng: number;
    };
  };
}

const containerStyle = {
  width: "100%",
  height: "500px",
};

const defaultCenter = {
  lat: 28.6139, 
  lng: 77.209,
};

const GOOGLE_MAPS_API_KEY = process.env.API_KEY as string;

const HotelFinder = () => {
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [mapCenter, setMapCenter] = useState(defaultCenter);

  const fetchHotels = async () => {
    if (!searchTerm) return;
  
    try {
    
      const geoResponse = await fetch(
        `https://maps.googleapis.com/maps/api/geocode/json?address=${searchTerm}&key=${GOOGLE_MAPS_API_KEY}`
      );
      const geoData = await geoResponse.json();
      console.log("🗺 Geocoding Response:", geoData);
  
      if (!geoData.results.length) {
        console.warn("⚠ No location found!");
        return;
      }
  
      const { lat, lng } = geoData.results[0].geometry.location;
      setMapCenter({ lat, lng });
  
     
      const placesResponse = await fetch(
        `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&radius=5000&type=lodging&key=${GOOGLE_MAPS_API_KEY}`
      );
      const placesData = await placesResponse.json();
      console.log("Places API Response:", placesData);
  
      if (placesData.status !== "OK") {
        console.error("API Error:", placesData.status);
      }
  
      setHotels(placesData.results || []);
    } catch (error) {
      console.error("Fetch error:", error);
    }
  };
  

  return (
    <div className="flex gap-5 p-5">
      <div className="w-3/5">
        <div className="mt-4">
          {hotels.length > 0 ? (
            hotels.map((hotel, index) => (
              <div key={index} className="p-3 border-b">
                <h3 className="text-lg font-semibold">{hotel.name}</h3>
                <p>{hotel.vicinity}</p>
              </div>
            ))
          ) : (
            <p className="text-gray-500">No hotels found</p>
          )}
        </div>
      </div>


      <div className="w-2/5">
        <LoadScript googleMapsApiKey={GOOGLE_MAPS_API_KEY}>
          <GoogleMap mapContainerStyle={containerStyle} center={mapCenter} zoom={14}>
            {hotels.map((hotel, index) => (
              <Marker key={index} position={hotel.geometry.location} />
            ))}
          </GoogleMap>
        </LoadScript>
      </div>
    </div>
  );
};

export default HotelFinder;
